var import_state2 = require("@codemirror/state");
var import_view2 = require("@codemirror/view");
function build2(state) {
  const builder = new import_state2.RangeSetBuilder();
  const text2 = state.doc.toString();
  const selections = state.selection.ranges;
  for (const gloss of findGlosses(text2)) {
    const editing = selections.some((range) => range.from <= gloss.end && range.to >= gloss.start);
    if (editing) {
      builder.add(gloss.start, gloss.end, import_view2.Decoration.mark({ class: "codazo-gloss-raw" }));
      continue;
    }
    builder.add(gloss.start, gloss.termStart, import_view2.Decoration.replace({}));
    builder.add(gloss.termStart, gloss.termEnd, import_view2.Decoration.mark({ class: "codazo-gloss", attributes: { title: gloss.gloss, "aria-label": gloss.gloss } }));
    builder.add(gloss.termEnd, gloss.end, import_view2.Decoration.replace({}));
  }
  return builder.finish();
}
function glossExtension() {
  const field = import_state2.StateField.define({
    create: build2,
    update: (value, transaction) => transaction.docChanged || transaction.selection ? build2(transaction.state) : value,
    provide: (field2) => import_view2.EditorView.decorations.from(field2)
  });
  return [field];
}
function glossPostProcessor(element, setTooltip2) {
  const walker = element.ownerDocument.createTreeWalker(element, NodeFilter.SHOW_TEXT);
  const nodes = [];
  for (let node2 = walker.nextNode(); node2; node2 = walker.nextNode()) if (node2.data.includes("{") && node2.data.includes("|")) nodes.push(node2);
  for (const node2 of nodes) {
    const glosses = findGlosses(node2.data);
    if (!glosses.length || node2.parentElement?.closest("code, pre")) continue;
    const fragment = element.ownerDocument.createDocumentFragment();
    let cursor = 0;
    for (const gloss of glosses) {
      if (gloss.start > cursor) fragment.appendChild(element.ownerDocument.createTextNode(node2.data.slice(cursor, gloss.start)));
      const span = element.ownerDocument.createElement("span");
      span.className = "codazo-gloss";
      span.textContent = gloss.term;
      span.setAttribute("aria-label", gloss.gloss);
      setTooltip2(span, gloss.gloss);
      fragment.appendChild(span);
      cursor = gloss.end;
    }
    fragment.appendChild(element.ownerDocument.createTextNode(node2.data.slice(cursor)));
    node2.replaceWith(fragment);
  }
}

