    const mark = el(paragraph, "button", { cls: `codazo-mark codazo-mark-${item.category} codazo-source-mark`, text: text2.slice(item.start, item.end), attrs: { type: "button", "data-annotation": item.id, "aria-label": `${text2.slice(item.start, item.end)}, ${item.label}` } });
