      kind,
      ...kind === "excerpt" && (excerptKind === "word" || excerptKind === "phrase" || excerptKind === "paragraph") ? { excerptKind } : {},
      notePath: sourceFile?.path ?? file2.path,
      source: review.source,
      sourceHash: sourceHash ?? await sha256Hex(review.source.text),
      offset: null,
      reviewedAt: reviewedAt ?? new Date(file2.stat.ctime).toISOString(),
      review,
      generatedBy: `${t().savedReviewLabel}${provider && model ? ` \xB7 ${provider} \xB7 ${model}` : ""}; AI may be wrong`,
      provider: provider ?? t().unknown,
      model: model ?? t().unknown,
